// Starts `threads` threads that all wait at one gate, then run body together.
// A failure on any thread is rethrown here, on the test thread.
void Race(int threads, Action body)
{
    using var gate = new ManualResetEventSlim(false);
    var errors = new List<Exception>();
    var workers = Enumerable.Range(0, threads).Select(_ => new Thread(() =>
    {
        gate.Wait();
        try { body(); }
        catch (Exception e) { lock (errors) errors.Add(e); }
    })).ToList();
    workers.ForEach(w => w.Start());
    gate.Set();
    workers.ForEach(w => w.Join());
    if (errors.Count > 0) throw errors[0];
}

