{
    var c = new HitCounter();
    Race(4, () => { for (int i = 0; i < 250_000; i++) c.Hit(); });
    Eq(c.Total, 1_000_000L);
});

Test("a fresh counter starts at 0 (boundary)", () =>
    Eq(new HitCounter().Total, 0L));

