// ──────────────────────────── types ──────────────────────────────────────

class ClientCache
{
    private readonly Func<string, object> _factory;
    private readonly ConcurrentDictionary<string, Lazy<object>> _pool = new();
    private int _factoryCalls;

    public ClientCache(Func<string, object> factory)
    {
        _factory = factory;
    }

    public int FactoryCalls => Volatile.Read(ref _factoryCalls);

    public object Get(string name) =>
        _pool.GetOrAdd(name, n => new Lazy<object>(() => Create(n))).Value;

    private object Create(string name)
    {
        Interlocked.Increment(ref _factoryCalls);
        return _factory(name);
    }
}

