// ──────────────────────────── types ──────────────────────────────────────

class LiveConfig
{
    private FrozenDictionary<string, string> _current = FrozenDictionary<string, string>.Empty;

    public void Reload(Dictionary<string, string> next)
    {
        var copy = next.ToFrozenDictionary();   // a private, read-optimized copy: never alias the caller's
        Volatile.Write(ref _current, copy);     // publish the whole version at once
    }

    public string? Get(string key)
    {
        var snapshot = Volatile.Read(ref _current);      // one read: one consistent version
        return snapshot.TryGetValue(key, out var value) ? value : null;
    }
}

