// ─────────────────────────────────────────────────────────────────────────
//  09 · bounded channel inbox                                  ★★☆ core
//  concepts: System.Threading.Channels · backpressure · full modes
// ─────────────────────────────────────────────────────────────────────────
//
//  Request threads produce, one background worker consumes. An unbounded
//  queue turns a slow consumer into an out-of-memory crash; a BOUNDED
//  channel turns it into a fast, visible "no" at the door.

using System.Threading.Channels;
using static Bootcamp.Check;

Channel<string> CreateInbox(int capacity)
{
    return Channel.CreateBounded<string>(new BoundedChannelOptions(capacity)
    {
        FullMode = BoundedChannelFullMode.Wait,   // awaited writers wait; TryWrite says false
        SingleReader = true,                      // one background worker drains it
    });
}

bool TryOffer(Channel<string> inbox, string msg)
{
    return inbox.Writer.TryWrite(msg);
}

async Task<List<string>> DrainAsync(Channel<string> inbox)
{
    inbox.Writer.Complete();
    var drained = new List<string>();
    await foreach (var msg in inbox.Reader.ReadAllAsync())
        drained.Add(msg);
    return drained;
}

