    var pending = inbox.Writer.WriteAsync("c").AsTask();
    Ok(!pending.IsCompleted, "a full inbox must make the writer wait, not drop a message");
    inbox.Reader.TryRead(out _);
    await pending;
    Eq(await DrainAsync(inbox), new[] { "b", "c" });
});

Test("DrainAsync returns what was waiting and closes the inbox", async () =>
{
    var inbox = CreateInbox(4);
    TryOffer(inbox, "x");
    TryOffer(inbox, "y");
    Eq(await DrainAsync(inbox), new[] { "x", "y" });
    Eq(TryOffer(inbox, "late"), false, "a drained inbox accepts nothing new");
    Ok(inbox.Reader.Completion.IsCompleted, "the reader has seen the end of the channel");
});

Test("draining an empty inbox -> [] (boundary)", async () =>
    Eq(await DrainAsync(CreateInbox(2)), Array.Empty<string>()));

