exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  10 · async concurrency limiter                              ★★★ stretch
//  concepts: SemaphoreSlim.WaitAsync · release in finally · cancellation
// ─────────────────────────────────────────────────────────────────────────
//
//  "At most N downloads at once": a lock admits ONE caller and cannot be
//  held across an await. A SemaphoreSlim admits N, waits asynchronously,
//  and must be released exactly once per permit actually taken.

using static Bootcamp.Check;

SemaphoreSlim CreateLimiter(int maxConcurrent)
{
    return new SemaphoreSlim(maxConcurrent, maxConcurrent);   // the max makes an extra Release throw
}

async Task<T> RunLimitedAsync<T>(SemaphoreSlim gate, Func<Task<T>> body, CancellationToken ct = default)
{
    await gate.WaitAsync(ct);   // a cancelled wait throws HERE, holding nothing
    try
    {
        return await body();
    }
    finally
    {
        gate.Release();         // exactly once per permit taken, even when body throws
    }
}

