// ──────────────────────────── tests ──────────────────────────────────────

Test("a limiter of 2 starts with 2 free permits", () =>
    Eq(CreateLimiter(2).CurrentCount, 2));

Test("at most 2 of 4 bodies run at once; the third starts only when one finishes (boundary)", async () =>
{
    var gate = CreateLimiter(2);
    var entered = Enumerable.Range(0, 4).Select(_ => new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously)).ToArray();
    var release = Enumerable.Range(0, 4).Select(_ => new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously)).ToArray();
    int inFlight = 0, maxInFlight = 0;
    var runs = Enumerable.Range(0, 4).Select(i => RunLimitedAsync(gate, async () =>
    {
        var now = Interlocked.Increment(ref inFlight);
        lock (entered) maxInFlight = Math.Max(maxInFlight, now);
        entered[i].SetResult();
        var value = await release[i].Task;
        Interlocked.Decrement(ref inFlight);
        return value;
    })).ToArray();
    foreach (var r in runs) if (r.IsFaulted) await r;   // surface an exception before waiting on bodies
    await Task.WhenAll(entered[0].Task, entered[1].Task);
    Ok(!entered[2].Task.IsCompleted && !entered[3].Task.IsCompleted, "only two bodies may be running");
    release[0].SetResult(10);
    await entered[2].Task;
    release[1].SetResult(11);
    release[2].SetResult(12);
    await entered[3].Task;
    release[3].SetResult(13);
    Eq(await Task.WhenAll(runs), new[] { 10, 11, 12, 13 });
    Eq(maxInFlight, 2);
    Eq(gate.CurrentCount, 2, "every permit came back");
});

Test("a body that throws still gives its permit back", async () =>
{
    var gate = CreateLimiter(1);
    await ThrowsAsync<InvalidOperationException>(async () =>
        await RunLimitedAsync<int>(gate, () => throw new InvalidOperationException("download failed")), "download failed");
    Eq(gate.CurrentCount, 1);
    Eq(await RunLimitedAsync(gate, () => Task.FromResult("next")), "next");
});

Test("a cancelled waiter never runs and never takes a permit (boundary)", async () =>
{
    var gate = CreateLimiter(1);
    var holder = new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);
    var first = RunLimitedAsync(gate, () => holder.Task);
    var cts = new CancellationTokenSource();
    bool secondRan = false;
    var second = RunLimitedAsync(gate, () => { secondRan = true; return Task.FromResult("second"); }, cts.Token);
    cts.Cancel();
    // the cancelled wait must end on its own, while the permit is still held (5 s is a hang guard only)
    await Task.WhenAny(second, Task.Delay(5000));
    Ok(second.IsCompleted, "a cancelled waiter must stop waiting without being given a permit");
    await ThrowsAsync<OperationCanceledException>(async () => await second);
    holder.SetResult("first");
    Eq(await first, "first");
    Eq(secondRan, false);
    Eq(gate.CurrentCount, 1, "the cancelled waiter gave nothing back because it held nothing");
});

Test("each caller gets its own body's result", async () =>
{
    var gate = CreateLimiter(3);
    var results = await Task.WhenAll(
        RunLimitedAsync(gate, () => Task.FromResult(1)),
        RunLimitedAsync(gate, () => Task.FromResult(2)));
    Eq(results, new[] { 1, 2 });
});
